using System.Windows; using System.Windows.Controls; using System.Windows.Media;
namespace AIEngineerStudio;
public class SettingsWindow:Window {
 public SettingsWindow(MainWindow owner){ Owner=owner; Title="Настройки приложения"; Width=580; Height=680; WindowStartupLocation=WindowStartupLocation.CenterOwner; Background=(Brush)owner.FindResource("PanelBg"); var root=new Grid{Margin=new Thickness(24)}; root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto}); root.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)}); root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto}); var title=new StackPanel(); title.Children.Add(new TextBlock{Text="Настройки приложения",Foreground=(Brush)owner.FindResource("Text"),FontSize=18,FontWeight=FontWeights.SemiBold}); title.Children.Add(new TextBlock{Text="Провайдер, модель, тема и системный промпт",Foreground=(Brush)owner.FindResource("Muted"),Margin=new Thickness(0,3,0,18)}); root.Children.Add(title); var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto}; var form=new StackPanel(); scroll.Content=form; Grid.SetRow(scroll,1); root.Children.Add(scroll); var token=Field(form,"API-токен / CVC_API_KEY",owner.ApiKey); var url=Field(form,"Base URL",owner.BaseUrl); var model=Field(form,"Модель",owner.Model); form.Children.Add(Label(owner,"Тема приложения")); var theme=new ComboBox{ItemsSource=new[]{"Graphite (по умолчанию)","Светлая","Midnight Blue","Emerald Night"},SelectedItem=owner.settings.Theme,Margin=new Thickness(0,4,0,14),Height=32}; form.Children.Add(theme); var temp=Field(form,"Температура (0.0–2.0)",owner.Temperature.ToString(System.Globalization.CultureInfo.InvariantCulture)); var max=Field(form,"Максимум токенов",owner.MaxTokens.ToString()); var python=Field(form,"Путь к Python",owner.PythonPath); var control=new CheckBox{Content="Разрешить агенту управлять мышью и рабочим столом",IsChecked=owner.ComputerControlEnabled,Margin=new Thickness(0,4,0,14)}; form.Children.Add(control); form.Children.Add(Label(owner,"Системный промпт по умолчанию")); var prompt=new TextBox{Text=owner.PromptTemplate,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,MinHeight=120,VerticalScrollBarVisibility=ScrollBarVisibility.Auto,Margin=new Thickness(0,4,0,14)}; form.Children.Add(prompt); var footer=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Right}; var cancel=new Button{Content="Отмена",Margin=new Thickness(0,14,8,0)}; cancel.Click+=(s,e)=>Close(); var save=new Button{Content="Сохранить настройки",Style=(Style)owner.FindResource("AccentButton"),Margin=new Thickness(0,14,0,0)}; save.Click+=(s,e)=>{owner.ApiKey=token.Text.Trim();owner.BaseUrl=url.Text.Trim();owner.Model=model.Text.Trim();owner.PythonPath=python.Text.Trim();owner.ComputerControlEnabled=control.IsChecked==true;owner.PromptTemplate=prompt.Text;owner.Temperature=double.TryParse(temp.Text,System.Globalization.NumberStyles.Float,System.Globalization.CultureInfo.InvariantCulture,out var t)?t:0.2;owner.MaxTokens=int.TryParse(max.Text,out var m)?m:8192;owner.SaveSettings();owner.SetTheme(theme.SelectedItem?.ToString()??"Graphite (по умолчанию)");Close();}; footer.Children.Add(cancel);footer.Children.Add(save);Grid.SetRow(footer,2);root.Children.Add(footer); Content=root; }
 static TextBlock Label(MainWindow o,string text)=>new(){Text=text,Foreground=(Brush)o.FindResource("Muted"),FontSize=11}; static TextBox Field(Panel p,string label,string value){p.Children.Add(new TextBlock{Text=label,Foreground=(Brush)Application.Current.Resources["Muted"],FontSize=11});var box=new TextBox{Text=value,MinHeight=32,Margin=new Thickness(0,4,0,14)};p.Children.Add(box);return box; }
}
public class PromptsWindow:Window { readonly MainWindow owner; readonly ListBox list; readonly TextBox name,editor; public PromptsWindow(MainWindow o){owner=o;Title="Библиотека системных промптов";Width=820;Height=560;Background=(Brush)o.FindResource("PanelBg");var grid=new Grid{Margin=new Thickness(20)};grid.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(250)});grid.ColumnDefinitions.Add(new ColumnDefinition());var left=new DockPanel();list=new ListBox{ItemsSource=o.settings.Prompts,DisplayMemberPath="Name",Background=(Brush)o.FindResource("SubBg"),Foreground=(Brush)o.FindResource("Body")};list.SelectionChanged+=(s,e)=>LoadSelected();DockPanel.SetDock(list,Dock.Top);left.Children.Add(list);var buttons=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,10,0,0)};var add=new Button{Content="＋ Создать",Margin=new Thickness(0,0,6,0)};add.Click+=(s,e)=>{var p=new SystemPrompt{Name="Новый промпт",Content=""};owner.settings.Prompts.Add(p);list.Items.Refresh();list.SelectedItem=p;};var del=new Button{Content="Удалить"};del.Click+=(s,e)=>{if(list.SelectedItem is SystemPrompt p){owner.settings.Prompts.Remove(p);owner.SaveSettings();list.Items.Refresh();}};buttons.Children.Add(add);buttons.Children.Add(del);DockPanel.SetDock(buttons,Dock.Bottom);left.Children.Add(buttons);grid.Children.Add(left);var right=new Grid{Margin=new Thickness(18,0,0,0)};right.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});right.RowDefinitions.Add(new RowDefinition());right.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});name=new TextBox{MinHeight=32,Margin=new Thickness(0,0,0,10)};right.Children.Add(name);editor=new TextBox{AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(editor,1);right.Children.Add(editor);var save=new Button{Content="Сохранить промпт",Style=(Style)o.FindResource("AccentButton"),HorizontalAlignment=HorizontalAlignment.Right,Margin=new Thickness(0,10,0,0)};save.Click+=(s,e)=>{if(list.SelectedItem is SystemPrompt p){p.Name=name.Text.Trim();p.Content=editor.Text;owner.SaveSettings();list.Items.Refresh();}};Grid.SetRow(save,2);right.Children.Add(save);Grid.SetColumn(right,1);grid.Children.Add(right);Content=grid;list.SelectedIndex=0;}
 void LoadSelected(){if(list.SelectedItem is SystemPrompt p){name.Text=p.Name;editor.Text=p.Content;}}
}
